/** Repository of the "audit_log" table: reads and writes rows, and decides nothing. */
import { asc, count } from 'drizzle-orm'
import type { Executor } from '../database.js'
import { AuditLog } from '../entities/audit-log.js'
import type { Page } from '../paging.js'
import { auditLog } from '../schema.js'

/** The AuditLog of a row Drizzle read. */
function toEntity(row: typeof auditLog.$inferSelect): AuditLog {
  return Object.assign(new AuditLog(), row)
}

/** Keeps audit_log rows in the database, through Drizzle. Every write is committed at once. */
export class SqlAuditLogRepository {
  constructor(private readonly db: Executor) {}

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<AuditLog>> {
    const rows = await this.db.select().from(auditLog).orderBy(asc(auditLog.at), asc(auditLog.message)).limit(limit).offset(offset)
    const [{ total }] = await this.db.select({ total: count() }).from(auditLog)
    return { items: rows.map(toEntity), total, offset, limit }
  }
}

