/** The tables of the database, as Drizzle reads and writes them. They reflect the database: do not migrate with them. */
import { sql } from 'drizzle-orm'
import { bigint, check, foreignKey, index, integer, numeric, pgTable, primaryKey, text, timestamp, unique, varchar } from 'drizzle-orm/pg-core'

/** The "customers" table. */
export const customers = pgTable(
  'customers',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedByDefaultAsIdentity(),
    email: varchar('email', { length: 120 }).notNull(),
    passwordHash: text('password_hash').notNull(),
    createdAt: timestamp('created_at', { mode: 'date', withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique('uq_customers_email').on(t.email),
  ],
)

/** The "categories" table. */
export const categories = pgTable(
  'categories',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedByDefaultAsIdentity(),
    name: varchar('name', { length: 60 }).notNull(),
  },
  (t) => [
    unique().on(t.name),
  ],
)

/** The "products" table. */
export const products = pgTable(
  'products',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedByDefaultAsIdentity(),
    categoryId: bigint('category_id', { mode: 'number' }).notNull(),
    name: varchar('name', { length: 100 }).notNull(),
    price: numeric('price', { precision: 10, scale: 2 }).notNull(),
    status: varchar('status', { length: 10 }).notNull(),
    version: integer('version').notNull().default(1),
    deletedAt: timestamp('deleted_at', { mode: 'date', withTimezone: true }),
  },
  (t) => [
    index('ix_products_status').on(t.status),
    index('products_category_id_idx').on(t.categoryId),
    check('products_check_1', sql.raw('price >= 0')),
    foreignKey({ name: 'fk_products_category', columns: [t.categoryId], foreignColumns: [categories.id] }),
  ],
)

/** The "orders" table. */
export const orders = pgTable(
  'orders',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedByDefaultAsIdentity(),
    customerId: bigint('customer_id', { mode: 'number' }).notNull(),
    placedAt: timestamp('placed_at', { mode: 'date', withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    foreignKey({ columns: [t.customerId], foreignColumns: [customers.id] }),
  ],
)

/** The "order_lines" table. */
export const orderLines = pgTable(
  'order_lines',
  {
    orderId: bigint('order_id', { mode: 'number' }).notNull(),
    line: integer('line').notNull(),
    productId: bigint('product_id', { mode: 'number' }).notNull(),
    quantity: integer('quantity').notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.orderId, t.line] }),
    foreignKey({ columns: [t.orderId], foreignColumns: [orders.id] }).onDelete('cascade'),
    foreignKey({ columns: [t.productId], foreignColumns: [products.id] }).onDelete('restrict'),
  ],
)

/** The "tags" table. */
export const tags = pgTable(
  'tags',
  {
    id: bigint('id', { mode: 'number' }).primaryKey().generatedByDefaultAsIdentity(),
    label: varchar('label', { length: 30 }).notNull(),
  }
)

/** The "product_tags" table. */
export const productTags = pgTable(
  'product_tags',
  {
    productId: bigint('product_id', { mode: 'number' }).notNull(),
    tagId: bigint('tag_id', { mode: 'number' }).notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.productId, t.tagId] }),
    foreignKey({ columns: [t.productId], foreignColumns: [products.id] }).onDelete('cascade'),
    foreignKey({ columns: [t.tagId], foreignColumns: [tags.id] }).onDelete('cascade'),
  ],
)

/** The "audit_log" table. */
// The table has no primary key: rows are told apart by all their columns, for reading only
export const auditLog = pgTable(
  'audit_log',
  {
    at: timestamp('at', { mode: 'date', withTimezone: true }).notNull(),
    message: text('message').notNull(),
  }
)

