  async createProduct(product: Product): Promise<Product> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries([...FIELDS].map((field) => [field, (product as unknown as Record<string, unknown>)[field]]))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.products.insert(product)
      return created
    })
  }

  /** The Product with this key; NotFoundError when there is none. */
  async getProduct(id: number): Promise<Product> {
    return await this.find(this.uow, id)
  }

