  }

  /** Stores a new Tag after checking it. */
  async createTag(tag: Tag): Promise<Tag> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries([...FIELDS].map((field) => [field, (tag as unknown as Record<string, unknown>)[field]]))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.tags.insert(tag)
      return created
    })
  }

  /** The Tag with this key; NotFoundError when there is none. */
  async getTag(id: number): Promise<Tag> {
    return await this.find(this.uow, id)
  }

  /** A page of tags, by primary key. */
  async listTags(offset = 0, limit = 50): Promise<Page<Tag>> {
    return this.uow.tags.list(offset, limit)
  }

  /** Changes the given values of a Tag. */
  async updateTag(id: number, changes: Partial<Tag>): Promise<Tag> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(changes).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.tags.update(current)
      return updated
    })
  }

  /** Deletes a Tag. */
  async deleteTag(id: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await uow.tags.delete(current)
    })
  }

  /** Links a Tag and a Product (product_tags). */
  async addProduct(tagId: number, productId: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      await this.find(uow, tagId)
      if ((await uow.products.getById(productId)) === null) throw new NotFoundError('Product', productId)
      if (await uow.productTags.getByProductIdAndTagId(productId, tagId) !== null) throw new ConflictError('Tag', 'is already linked to this Product', ['productId'])
      await uow.productTags.insert(Object.assign(new ProductTag(), { tagId, productId }))
    })
  }

  /** Removes the link between a Tag and a Product (product_tags). */
  async removeProduct(tagId: number, productId: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const link = await uow.productTags.getByProductIdAndTagId(productId, tagId)
      if (link === null) throw new NotFoundError('ProductTag', [productId, tagId])
      await uow.productTags.delete(link)
    })
  }
}

