/** A valid Customer that is not stored yet; `n` makes its unique values differ, `values` replace any of them. */
export function newCustomer(n = 1, values: Partial<Customer> = {}): Customer {
  return Object.assign(new Customer(), { email: `email-${n}`, passwordHash: `passwordhash-${n}` }, values)
}

/** A stored Customer. */
export async function addCustomer(uow: UnitOfWork, n = 1): Promise<Customer> {
  return uow.customers.insert(newCustomer(n))
}

